from contextlib import contextmanager

@contextmanager
def run_flag(state):
    state['active'] = True
    try:
        yield state
    finally:
        state['active'] = False

state = {'active': False}
for fail in [False, True]:
    try:
        with run_flag(state):
            print(state['active'])
            if fail:
                raise ValueError('practice')
    except ValueError:
        print('caught')
    print(state['active'])
